{"command": "python3 - <<'PY'
import json, glob, os
from collections import Counter
files=sorted(glob.glob('orders/*.json'))
bad=[]
types=Counter()
cats=Counter()
for f in files:
    try:
        d=json.load(open(f))
    except Exception as e:
        bad.append(os.path.basename(f)); print('BAD',f,repr(e)); continue
    types[type(d).__name__]+=1
    if isinstance(d,dict):
        cats[d.get('category')]+=1
        if not isinstance(d.get('amount_cents'),(int,float)) or isinstance(d.get('amount_cents'),bool):
            print('AMOUNT TYPE',f,repr(d.get('amount_cents')))
    else:
        print('NONOBJ',f,repr(d)[:100])
print('files',len(files),'bad',len(bad),bad)
print('types',types)
print('cats',cats)
PY", "description": "Parse orders and inspect structure and errors"}

